class Solution {
    private static final long LIMIT = 1_000_000_000L;

    public int longestSquareStreak(int[] nums) {
        java.util.Set<Long> values = new java.util.HashSet<>();
        for (int num : nums) {
            values.add((long) num);
        }

        int best = 1;
        for (long start : values) {
            long current = start;
            int length = 0;
            while (values.contains(current)) {
                length++;
                if (current == 1 || current > LIMIT / current) {
                    break;
                }
                current *= current;
            }
            best = Math.max(best, length);
        }
        return best >= 2 ? best : -1;
    }
}

class Solution {
    public int longestSquareStreak(int[] nums) {
        java.util.TreeSet<Integer> sorted = new java.util.TreeSet<>();
        for (int num : nums) {
            sorted.add(num);
        }

        java.util.Map<Integer, Integer> dp = new java.util.HashMap<>();
        int best = 1;
        for (int value : sorted) {
            int length = 1;
            int root = (int) Math.sqrt(value);
            if (value != 1 && root * root == value && dp.containsKey(root)) {
                length = dp.get(root) + 1;
            }
            dp.put(value, length);
            best = Math.max(best, length);
        }
        return best >= 2 ? best : -1;
    }
}

class Solution {
    private static final long LIMIT = 1_000_000_000L;

    public int longestSquareStreak(int[] nums) {
        java.util.Set<Integer> values = new java.util.HashSet<>();
        for (int num : nums) {
            values.add(num);
        }

        int best = 1;
        for (int value : values) {
            if (value == 1 || hasSquareRootInSet(value, values)) {
                continue;
            }
            long current = value;
            int length = 0;
            while (current <= LIMIT && values.contains((int) current)) {
                length++;
                if (current > LIMIT / current) {
                    break;
                }
                current *= current;
            }
            best = Math.max(best, length);
        }
        return best >= 2 ? best : -1;
    }

    private boolean hasSquareRootInSet(int value, java.util.Set<Integer> values) {
        int root = (int) Math.sqrt(value);
        return root * root == value && values.contains(root);
    }
}

class Solution {
    private static final long LIMIT = 1_000_000_000L;
    private java.util.Set<Long> values;
    private java.util.Map<Long, Integer> memo;

    public int longestSquareStreak(int[] nums) {
        values = new java.util.HashSet<>();
        for (int num : nums) {
            values.add((long) num);
        }
        memo = new java.util.HashMap<>();

        int best = 1;
        for (long value : values) {
            best = Math.max(best, dfs(value));
        }
        return best >= 2 ? best : -1;
    }

    private int dfs(long value) {
        if (memo.containsKey(value)) {
            return memo.get(value);
        }
        int length = 1;
        if (value != 1 && value <= LIMIT / value) {
            long next = value * value;
            if (values.contains(next)) {
                length = 1 + dfs(next);
            }
        }
        memo.put(value, length);
        return length;
    }
}
